registerRefData('nsw-cond-n-143',{"id":143,"pan":null,"ref":"DA/683/2024","address":"17 Lucca Road Wyong 2259","description":"Industrial - Metal Recycling Plant","outcome":"deferred_commencement","outcome_raw":"Deferred commencement consent","outcome_source":"planning_panels","determined":"2025-12-10","notice_url":"https://apps.planningportal.nsw.gov.au/prweb/PRRestService/DocMgmt/v1/PublicDocuments/DATA-WORKATTACH-FILE PEC-DPE-EP-WORK PPSHCC-293!20251210T041609.091 GMT","sha256":"26ab78eb7e8877cef0a5190d82d1593598343c089d165e04e2351676c997d99d","pages":26,"layout":"numbered","n":10,"fetched_at":"2026-08-16T23:19:06+00:00","file":"n/143.js","source_page":"https://www.planningportal.nsw.gov.au/planning-panel/industrial-metal-recycling-plant","lga":"CENTRAL COAST","conditions":[{"label":"1","code":null,"number":"1","title":"","text":"PANEL REF - LGA - DA NO. PPSHCC-293 - Central Coast - DA/683/2024","stage":"general","stage_basis":"heading","page":3},{"label":"2","code":null,"number":"2","title":"PROPOSED DEVELOPMENT Industrial - Metal Recycling Plant","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"3","code":null,"number":"3","title":"STREET ADDRESS 17 Lucca Road, Wyong 2259","text":"","stage":"general","stage_basis":"heading","page":3},{"label":"4","code":null,"number":"4","title":"APPLICANT/OWNER Raybal Constructions Pty Limited","text":"Gurraj Pty Ltd","stage":"general","stage_basis":"heading","page":3},{"label":"5","code":null,"number":"5","title":"TYPE OF REGIONAL","text":"DEVELOPMENT Designated development - waste management facility or works","stage":"general","stage_basis":"heading","page":3},{"label":"6","code":null,"number":"6","title":"RELEVANT MANDATORY","text":"CONSIDERATIONS\n• Environmental planning instruments:\no State Environmental Planning Policy (Biodiversity and Conservation) 2021\no State Environmental Planning Policy (Resilience and Hazards) 2021\no State Environmental Planning Policy (Planning Systems) 2021\no State Environmental Planning Policy (Transport and Infrastructure) 2021\no State Environmental Planning Policy (Industry and Employment) 2021\no Central Coast Local Environmental Plan 2022\n• Draft environmental planning instruments: Nil\n• Development control plans:\no Central Coast Development Control Plan 2022\n• Planning agreements: Nil\n• Provisions of the Environmental Planning and Assessment Regulation 2021: Nil\n• Coastal zone management plan: Nil\n• The likely impacts of the development, including environmental impacts on\nthe natural and built environment and social and economic impacts in the\nlocality\n• The suitability of the site for the development\n• Any submissions made in accordance with the Environmental Planning and\nAssessment Act 1979 or regulations\n• The public interest, including the principles of ecologically sustainable\ndevelopment","stage":"general","stage_basis":"heading","page":3},{"label":"7","code":null,"number":"7","title":"MATERIAL CONSIDERED BY","text":"THE PANEL\n• Council assessment report: 25 November 2025\n• Council memo: 2 December 2025\n• Written submissions during public exhibition: 1\n• Total number of unique submissions received by way of objection: 1","stage":"general","stage_basis":"heading","page":3},{"label":"8","code":null,"number":"8","title":"MEETINGS, BRIEFINGS AND","text":"SITE INSPECTIONS BY THE\nPANEL\n• Initial Briefing: 27 August 2024\no Panel members: Alison McCabe (Chair), Roberta Ryan, Greg Flynn\no Council assessment staff: Salli Pendergast, Emily Goodworth\no Applicant representative: Fabian Ceolin\n• Site inspection:\no Alison McCabe: 5 July 2024\no Roberta Ryan: 26 April 2025\no Rachel Stanton: 24 August 2025\no Doug Eaton: 20 February 2025\n• Final briefing to discuss council’s recommendation: 2 December 2025\no Panel members: Alison McCabe (Chair), Roberta Ryan, Rachel Stanton,\nDoug Eaton\no Council assessment staff: Salli Pendergast\no Applicant representatives: Lisa Wrightson, Fabian Ceolin","stage":"general","stage_basis":"heading","page":3},{"label":"9","code":null,"number":"9","title":"COUNCIL RECOMMENDATION","text":"Deferred Commencement","stage":"general","stage_basis":"heading","page":3},{"label":"10","code":null,"number":"10","title":"DRAFT CONDITIONS Attached to the council assessment report","text":"DEFFERRED COMMENCEMENT\nSchedule A - Deferred Commencement\n“Deferred Commencement” consent is granted in accordance with sub-section 4.16(3) of the\nEnvironmental Planning and Assessment Act 1979.\nThis consent does not operate until the following have been satisfied:\na) A Building Information Certificate has been issued for the larger demountable structure\nlabelled “office/administration building” on the site plan.\nEvidence must be produced to the consent authority sufficient to enable it to be satisfied\nthat above conditions have been complied within six (6) months of the date of this approval,\notherwise this consent will lapse.\nUpon compliance with the conditions of deferred commencement (under Schedule A)\nCouncil will issue an operative 2 year consent (including stamped plans) that is subject to the\nattached conditions under Schedule B below.\nSchedule B\n1. PARAMETERS OF THIS CONSENT\n1.1 Development must be carried out in accordance with the following approved plans and\nsupporting documentation (stamped by Council), except where the conditions of this\nconsent expressly require otherwise.\nArchitectural Plans:\nDescription/Title\nDrawing\nNo Rev Date Author\nSite Plan 22016 A0001 7 30.06.25 MABD\nFloor Plans A011 1 07.07.25 MABD\nElevations and Sections A101 1 07.07.25 MABD\nLandscape Plan - Cover page L01 D 23.06.25 GSP\nPlanting Plan L02 D 23.06.25 GSP\nDetails L03 D 23.06.25 GSP\nLandscape Notes L04 D 23.06.25 GSP\nSupporting Documentation\nDocument Title Date\nD16189880 Environmental Impact Statement prepared by Barker\nRyan Stewart, project no.230310, Rev. 2\nAs amended by correspondence (D17051232) dated 29\nAugust 2025.\n12.04.24\nSCHEDULE 2\nD16189866 Traffic and Parking Impact Assessment prepared by\nBarker Ryan Stewart, Rev. 3\n22.03.24\nD16189867 Visual Impact Assessment, prepared by Barker Ryan\nStewart, Rev. 2\n12.04.24\nD16189868 Waste Management Plan prepared by Barker Ryan\nStewart, Rev. 2\n12.04.24\nD16189869 Streamlined Biodiversity Development Assessment\nReport (amended), Project no.RAYB2, Version. Final V4.0\n29.10.25\nD16189870 Air Quality Impact Assessment prepared by Northstar,\nRef. 24.1035.FR1V1, Final\n18.03.24\nD16189872 Noise Assessment prepared by Muller Acoustic\nConsulting, Ref. MAC232034-01RP1V1\n28.03.24\nD16189876 Bush Fire Assessment Report prepared by Clarke Dowdle\n& Associates, Final, Ver.5\n15.03.24\nD17051195 Preliminary (Environmental) Site Investigation prepared\nby Sanko, Doc -E25 022-A, Issue 1.\n26.06.25\nD17051207 Preliminary Sample and Analysis Quality Plan (SAQP),\nprepared by Sanko, Doc - E25 022_B, Issue 1.\n01.04.25\nD17051204 Civil Engineering Plans No.C101- B (22.04.24),\nC102-D, C103-D, C104-D, C105, C106, prepared by\nEclipse Consulting Engineers.\n18.07.25\nD17051210 Engineering Stormwater Design prepared by Barker Ryan\nStewart, Project No. 230310-01, Plan No. 001, 011, 101,\n505, 511, 512, 521, 601, 701, 702, Revision D\n07.08.25\nD17051205 Arboricultural Impact Assessment Report prepared by\nBlues Brothers Arboriculture, Version 2\n02.07.25\nD16189851 Heritage Desktop Assessment prepared by Barker Ryan\nStewart, Ver 2.\n12.04.25\nD16189855 Planning Secretary’s Environmental Assessment\nRequirements (SEAR) 1793\n03.07.25\nD16189856 Hazards Assessment - SEPP (Resiliance and Hazards)\nprepared by Northstar Air Quality P/L, Ref.24.1035.FR2V1.\n18.03.24\nD16189857 Fire Service Upgrade prepared by Glenn Haig & Partners,\ndrawing H000, H001 &H002 issue A, and certification.\n14.02.24\nD16189858 Policies and procedures- Rev. 3- Various 19.03.24\nD16189861 Operations and Management Plan, prepared by Barker\nRyan Stewart, Rev 2.\n12.04.24\nD16189863 Stormwater Management and Flood Impact Assessment\nReport, prepared by Barker Ryan Stewart, Rev. 2\n12.04.24\nD16720093 Survey Plan prepared by Clarke Dowdle & Assoc,\nRef.25540, 1 of 1.\n29.09.22\nIn the event of any inconsistency between the approved plans and the supporting\ndocumentation, the approved plans prevail. In the event of any inconsistency between\nthe approved plans and a condition of this consent, the condition prevails.\nThe recommendations of the supporting documentation above are to be implemented\nas part of the development during the relevant stages of construction and operation\nexcept as otherwise specifically stated under the conditions below.\nNote: an inconsistency occurs between an approved plan and supporting\ndocumentation or between an approved plan and a condition when it is not possible to\ncomply with both at the relevant time.\n1.2 Carry out all building works in accordance with the National Construction Code Series,\nBuilding Code of Australia, Volume 1 and 2 as appropriate.\n1.3 Comply with the General Terms of Approval / requirements from the Authorities as listed\nbelow and attached as a schedule of this consent.\nGovernment\nAgency /\nDepartment /\nAuthority\nDescription Ref No Date\nNSW Rural Fire\nService\nS4.14 recommended\nconditions\nS.38 - Compliance with\noriginal dated 22.09.25\nDA20240522002109-\nOriginal-1\n31 May\n2024\nTransport for NSW Correspondence - advice A-83784 12 June\n2024\nNSW Environment\nProtection\nAuthority\nGeneral Terms of\nApproval Notice No. 1640430 24 July\n2024\nAusgrid Correspondence\nproviding comment 1900155183 24 Nov\n2025\n1.4 A Construction Certificate is to be issued by the Principal Certifying Authority prior to\ncommencement of any construction works. The application for this Certificate is to\nsatisfy all of the requirements of the Environmental Planning and Assessment\n(Development Certification and Fire Safety) Regulation 2021.\n1.5 Prior to the occupation or use of the building/structure, an application for an\nOccupation Certificate for the development must be submitted to and approved by the\nPrincipal Certifying Authority. The Occupation Certificate application is to satisfy all of\nthe requirements of the Environmental Planning and Assessment (Development\nCertification and Fire Safety) Regulation 2021.\n1.6 Where conditions of this consent require approval from Council under Section 138 of\nthe Roads Act 1993, Section 68 of the Local Government Act 1993 or Section 305 of the\nWater Management Act 2000, a completed Works application form must be lodged with\nCouncil and be accompanied by detailed design drawings and supporting information.\nUpon submission to Council, fees and charges will be calculated in accordance with\nCouncil’s Management Plan. The fees and charges must be paid prior to Council\ncommencing the design assessment.\n1.7 The waste types and volume permitted to be accepted for recovery or storage at the\nsite are to be in accordance with the EPL and limited to:\n• Activity: Scrap metal processing\n• Maximum amount of waste permitted to be received at the premises per year:\n25,000 tonnes\n• Waste Type/ materials permitted to be accepted for processing: scrap metals\n(ferrous and non-ferrous)\n• Maximum Lead Acid Battery storage capacity of 5 tonnes at any one time.\nAny other waste types are not permitted to be stored at the site without the prior\nconsent of the Council.\n1.8 Obtain an Environmental Protection Licence from the New South Wales Environment\nProtection Authority.\n1.9 Following the granting of consent, the current unauthorised use of the site is to cease\noperation. All external metal storage stockpiles are to be removed from the site until\nthe issue of an Occupation Certificate.\n2. PRIOR TO ISSUE OF ANY CONSTRUCTION CERTIFICATE\n2.1 All conditions under this section must be met prior to the issue of any Construction\nCertificate.\n2.2 No activity is to be carried out on-site until the Construction Certificate has been\nissued, other than:\na) Site investigation for the preparation of the construction, and / or\nb) Implementation of environmental protection measures, such as erosion control\nand the like that are required by this consent\nc) Demolition.\n2.3 Submit amendments to the approved plans to the Accredited Certifier that must detail:\na) The proposed 4m high boundary screening fence is to be extended as follows:\ni. - along the western side boundary up to the proposed (western side)\nlandscaped area, and\nii. - along the eastern side boundary up to No.17-19 Pavitt Cres.\nb) The concrete block wall around each stock pile (parallel to the side boundary) are\nto be increased in height to 4m.\nc) The concrete block wall around each stock pile is to be extended alongside the\nrear boundary to provide a continuous 1m setback to the boundary (at a wall\nheight of a minimum of 1.2m in height and a boundary setback of 1m).\nd) To cater for fluctuations in demand, the concrete block wall around each stock\npile is to be extended along the side boundaries (for a distance of around 15m)\nto provide an overflow stockpile area with a continuous 1m setback to the\nboundary.\ne) All stockpiles and stored waste on the site are to remain at all times setback 1m\nfrom and well clear of any boundary fencing.\nf) Appropriate vehicle protection for the proposed Ausgrid substation is to be\nshown on the plans in order to prevent accidental impact.\ng) The front fence is to be indented around the proposed substation kiosk to allow\n24/7 access for Ausgrid employees from the street.\nh) The deletion of the smaller (middle) demountable structure labelled “existing\nstaff/lunchroom”.\ni) The removal of any existing office areas from the shed into the front\ndemountable labelled “office/administration building”.\nj) A revised Landscape plan is to be prepared that clearly shows:\ni. Revised substation location (clear of egress manoeuvring)\nii. Replacement tree planting for 1 x spotted gum within the front\nsetback landscaped area.\niii. Details for the landscaping planting along the rear boundary.\n2.4 Before the issue of a Construction Certificate pursuant to Section 7.11 of the\nEnvironmental Planning & Assessment Act, the applicant must pay the following\ncontributions to Council for:\nThe total contribution payable to Council under this condition is $167,252.79 as\ncalculated at the date of this consent, in accordance with the Warnervale District\nSection 7.11 Plan 2021.\nThe total amount payable may be adjusted at the time the payment is made, in\naccordance with the provisions of Warnervale District Section 7.11 Plan 2021.\nContributions under Warnervale District Section 7.11 Plan 2021 are subject to quarterly\nindexation by CPI.\nA copy of the Contributions Plan is available for inspection at 2 Hely St, Wyong or on\nCouncil's website: https://www.centralcoast.nsw.gov.au/plan-and-build/development-\ncontributions-plans-and-planning-agreements.\n2.5 Submit to the Principal Certifier for any building structure, detailed design drawings\napproved by a suitably qualified Structural Engineer that have been prepared in\naccordance with the requirements of the Hawkesbury-Nepean Floodplain Management\nSteering Committee publication Reducing Vulnerability of Buildings to Flood Damage -\nGuidance on Building in Flood Prone Areas, Before the issue of any Construction\nCertificate, for the following flooding characteristics applicable to the development:\n(1) 1% Annual Exceedance Probability (AEP) flood level of Reduced Level (RL) 6.19\nmetres Australian Height Datum (AHD).\n(2) A minimum floor level of Reduced Level (RL) 6.19 metres Australian Height Datum\n(AHD).\n(3) Average flood velocity of 0.5 metres per second.\nAn appropriate factor of safety must be applied to the forces exerted by the 1%\nAnnual Exceedance Probability (AEP) flood before it is used in any structural\ncalculations.\n2.6 Obtain a Roads Act Works Approval by submitting an application to Council for a\nSection 138 Roads Act Works Approval for all works required within the road reserve.\nThe application is to be lodged using an Application for Subdivision Works Certificate\nor Construction Certificate, Roads Act Works Approval and other Development\nrelated Civil Works form.\nThe application is to be accompanied by detailed design drawings, reports and other\ndocumentation prepared by a suitably experienced qualified professional in\naccordance with Council’s Civil Works Specifications.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application. Fees must be paid prior to Council\ncommencing assessment of the application.\nDesign drawings, reports and documentation will be required to address the\nfollowing works within the road reserve:\na) Construction of 2 industrial/commercial vehicle access crossings in accordance\nwith the Engineering plans submitted with the application including\nconstruction of a heavy-duty gutter crossing and road pavement adjacent to\nthe gutter crossing. A structural design to cater for anticipated loadings and\ndetailing all concrete element must be provided.\nb) Construction of a 2 kerb inlet pits either side of the proposed exit driveway\ngenerally in accordance with the Engineering plans submitted with the\napplication. The eastern pit will need to be located east of the proposed\nelectricity substation.\nc) Construction of piped drainage system from the 2 kerb inlet pits across Lucca\nRoad to the existing stormwater drainage pit. This will require reconstruction of\nthis pit and the decommissioning of the existing stormwater pipe system in\naccordance with Council’s requirements.\nd) Removal of the damaged drainage pit and replace with new kerb and channel.\ne) Reconnection of the drainage pipe within the easement on the western side of\nthe site to the new kerb inlet pit on the western side of the exit driveway.\nf) Construction of all necessary road pavement associated with the stormwater\nconstruction works. In Lucca Road.\ng) Construction of any works required to transition new works into existing\ninfrastructure and the surrounding land formation.\nThe section 138 Roads Act Works Approval must be issued by Council, and all\nconditions of that approval must be addressed prior to occupying and commencing\nany works in the road reserve.\n2.7 Obtain a Section 68 Local Government Act Works Approval for Stormwater Drainage\nworks by submitting an application to Council for a ‘Section 68 Local Government Act\nWorks Approval - stormwater drainage’ for storm water drainage works connecting to\nor within Council’s storm water system using an Application for Subdivision Works\nCertificate or Construction Certificate, Roads Act Works Approval and other\nDevelopment related Civil Works form.\nThe application is to be accompanied by detailed design drawings, reports and other\ndocumentation prepared by a suitably experienced qualified professional in\naccordance with Council’s Civil Works Specifications.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application. Fees must be paid prior to Council\ncommencing assessment of the application.\nDesign drawings, reports and documentation will be required to address the following\nworks:\na) Construction of a storm water drainage connection from the development site\nto the new kerb inlet pit on the eastern side of the exit driveway. This shall\ninclude a reflux valve prior to the connection point with Council’s system to\nensure flood waters from minor events don’t enter the stormwater facility.\nThe Section 68 Local Government Act Works Approval - stormwater drainage must be\nissued and all conditions of that approval addressed prior to commencing any works\nthat are the subject of the approval.\n2.8 Submit to Council a dilapidation report detailing the condition of all Council assets\nwithin the vicinity of the development. The report must document and provide\nphotographs that clearly depict any existing damage to the road, kerb, gutter,\nfootpath, driveways, street trees, street signs, streetlights or any other Council assets in\nthe vicinity of the development. The dilapidation report will be required to be\nsubmitted to Council prior to the issue of the Section 138 Roads Act Works approval or\nthe issue of any construction certificate for works on the site. The dilapidation report\nmay be updated with the approval of Council prior to the commencement of works.\nThe report will be used by Council to establish damage to Council’s assets resulting\nfrom the development works.\n2.9 Submit to the Registered Certifier responsible for issuing the construction certificate\nfor works within the development site detailed design drawings and design reports for\nthe following engineering works:\na) Construction of driveways, ramps and car parking areas in accordance with\nthe requirements of the current edition Australian Standard AS/NZS 2890:\nParking Facilities and other applicable Australian Standards.\nb) Construction of a stormwater detention system. Design generally in\naccordance with the Engineering plans submitted with the application. An on-\nsite stormwater detention report including an operation and maintenance\nplan must accompany the design.\nc) Construction of nutrient and pollution control measures. Design in\naccordance with the Engineering plans submitted with the application. A\nnutrient and pollution control report including an operation and maintenance\nplan must accompany the design\nd) Construction of retaining walls were indicated on development approval\ndocumentation. Retaining wall design must not conflict with existing or\nproposed services or utilities. Retaining walls designs for wall greater than\n600mm in height must be certified by a registered practising Civil or Structural\nengineer as being in accordance with Australian Standards.\ne) Provide details of the required work area (easement area) around the\nproposed Electrical Substation which is to be clear of the vehicle clearance\nrequirements for turning movements for a Semi Trailer in accordance with\nAS2890 and Austroads guidelines. This may require the Electrical substation to\nbe located further east. This will also need at have consideration for the\nrelevant Electrical Authorities Network Standard for Electrical substations in\nflood prone areas. Any relocation is to ensure there is minimal impact on the\nproposed landscaping area.\nDetailed design drawings and design reports acceptable to the Registered Certifier\nmust be included in the Construction Certificate documentation.\n2.10 Submit an application to Council under section 305 of the Water Management Act\n2000 for a section 306 Requirements Letter. The Application form can be found on\nCouncil’s website centralcoast.nsw.gov.au. Early application is recommended.\nThe section 305 application will result in a section 306 letter of requirements which\nmust be obtained prior to the issue of any Construction Certificate. The requirements\nletter will outline which requirements must be met prior to each development\nmilestone e.g. prior to construction certificate, subdivision works certificate, occupation\ncertificate and/or subdivision certificate.\n2.11. Comply with and implement all impact mitigation recommendations and measures\noutlined in the submitted Environmental Impact Statement (Baker Ryan Stewart, April\n2024) and ecological impact mitigation measures outlined in Section 6 of the\nsupporting Biodiversity Development Assessment Report (Narla Environmental,\nOctober 2025) and tree protection measures outlined in the supporting Arboricultural\nImpact Assessment (Blues Bros Arboriculture, July 2025).\nWhere the recommendations contained within the Environmental Impact Statement,\nBiodiversity Development Assessment Report and Arboricultural Impact Assessment\nare inconsistent, the conditions of consent prevail.\n2.12. Identify trees and native vegetation proposed for retention and those approved for\nremoval must be clearly marked on all final engineering and landscaping plans. All\nfenced tree protection areas must be clearly marked as \"No Go Area\" on all plans.\n2.13 Submit to Council for approval a routine storm water quality monitoring program\ndeveloped by a duly qualified person. The monitoring program must include validation\ntesting and ongoing testing occurring every month for a period of 3 months, at a\nminimum. Water samples must be analysed by a NATA accredited laboratory, the\nanalytical results must be reviewed against ANZECC water quality guidelines for all\ncontaminants of concern and corrective actions must be included for elevated results.\n2.14 The management and mitigation measures identified under Section 9 and 10 of the EIS\nprepared by Barker Ryan Stewart are to be implemented as part of the development.\n2.15 The facade (and visible returns) of the demountable office is to be painted/finished in a\nvisually recessive colour or a similar upgrading treatment is to be applied to improve\nthe appearance of the demountable structure to the street.\n2.16 Prior to issue of a Construction Certificate, the developer is to provide Ausgrid with\nsufficient evidence that the new development will comply with Ausgrid’s minimum\nstatutory clearances in relation to the pole relocation works. (Refer to Ausgrid advice\ndated 24/11/25).\n3. PRIOR TO COMMENCEMENT OF ANY WORKS\n3.1 All conditions under this section must be met prior to the commencement of any\nworks.\n3.2 No activity is to be carried out on-site until the Construction Certificate has been\nissued, other than:\na) Site investigation for the preparation of the construction, and / or\nb) Implementation of environmental protection measures, such as erosion control\nand the like that are required by this consent\nc) Demolition approved by this consent.\n3.3 Appoint a Principal Certifying Authority for the building work:\na) The Principal Certifying Authority (if not Council) is to notify Council of their\nappointment and notify the person having the benefit of the development\nconsent of any critical stage inspections and other inspections that are to be\ncarried out in respect of the building work no later than two (2) days before the\nbuilding work commences.\nb) Submit to Council a Notice of Commencement of Building Works or Notice of\nCommencement of Subdivision Works form giving at least two (2) days’ notice of\nthe intention to commence building or subdivision work. The forms can be found\non Council’s website: www.centralcoast.nsw.gov.au\n3.4 Erect a sign in a prominent position on any work site on which building, subdivision or\ndemolition work is being carried out. The sign must indicate:\na) The name, address and telephone number of the Principal Certifying Authority\nfor the work; and\nb) The name of the principal contractor and a telephone number at which that\nperson can be contacted outside of working hours; and\nc) That unauthorised entry to the work site is prohibited.\nd) Remove the sign when the work has been completed.\n3.5 Install run-off and erosion controls to prevent soil erosion, water pollution or the\ndischarge of loose sediment on the surrounding land by:\n• erecting a silt fence and providing any other necessary sediment control\nmeasures that will prevent debris escaping into drainage systems, waterways or\nadjoining properties, and\n• diverting uncontaminated run-off around cleared or disturbed areas, and\n• preventing the tracking of sediment by vehicles onto roads, and\n• stockpiling topsoil, excavated materials, construction and landscaping supplies\nand debris within the lot.\n3.6 Erect a temporary hoarding or temporary construction site fence between the work site\nand adjoining lands before the works begin and must be kept in place until after the\ncompletion of the works, if the works:\na) could cause a danger, obstruction or inconvenience to pedestrian or vehicular\ntraffic, or\nb) could cause damage to adjoining lands by falling objects, or\nc) involve the enclosure of a public place or part of a public place.\nNote 1: A structure on public land or on or over a public road requires the prior\napproval of the relevant authority under the Local Government Act 1993 or the Roads\nAct 1993, respectively.\nNote 2: The Work Health and Safety Act 2011 and Work Health and Safety Regulation\n2011 contain provisions relating to scaffolds, hoardings and other temporary\nstructures.\n3.7 Sediment control fencing must remain in place until such time as the site is landscaped\nor turf is established.\nNote: Discharge of sediment from a site may be determined to be a pollution event\nunder provisions of the Protection of the Environment Operations Act 1997. Enforcement\naction may commence where sediment movement produces a pollution event.\n3.8 Provide or make available toilet facilities at the work site before works begin and\nmaintain the facilities until the works are completed at a ratio of one toilet plus one\nadditional toilet for every twenty (20) persons employed at the site.\nEach toilet must:\na) be a standard flushing toilet connected to a public sewer, or\nb) have an on-site effluent disposal system approved under the Local Government\nAct 1993, or\nc) be a temporary chemical closet approved under the Local Government Act 1993.\n3.9 Where required, submit both a Plumbing and Drainage Inspection Application, with the\nrelevant fee, and a Plumbing and Drainage Notice of Work in accordance with the\nPlumbing and Drainage Act 2011 (to be provided by licensed plumber). These\ndocuments can be found on Council’s website at: www.centralcoast.nsw.gov.au\nContact Council prior to submitting these forms to confirm the relevant fees.\n3.10 Submit to Council a completed Notice of Intention to Commence Subdivision, Roads\nand Stormwater Drainage Works form with supporting documentation prior to the\ncommencement of any Subdivision Works Certificate works, Roads Act Works Approval\nworks, or Section 68 Local Government Act Stormwater Drainage Works Approval\nworks. These works are not to commence until a pre-commencement site meeting has\nbeen held with Council.\n3.11 Submit a Hoarding Application to Council for approval under the Roads Act where it is\nproposed to erect construction fencing, a hoarding, site sheds or utilise the road\nreserve for any construction activity related to the development works within the site.\nFees, in accordance with Council’s Fees and Charges, will be invoiced to the applicant\nfollowing lodgement of the application and will be required to be paid prior to Council\nreleasing any approval.\n3.12 Prepare a Construction Traffic and Pedestrian Management Plan (CTPMP) for all\nactivities related to works within the site. The plan must be prepared and implemented\nonly by persons with Roads and Maritime Service accreditation for preparing and\nimplementing traffic management plans at work sites.\nThe CTPMP must describe the proposed construction works, the traffic impacts on the\nlocal area and how these impacts will be addressed.\nThe CTPMP must address, but not be limited to, the following matters:\n• Ingress and egress of construction related vehicles to the development site.\n• Details of the various vehicle lengths that will be used during construction\nand the frequency of these movements.\n• Use of swept path diagrams to demonstrate how heavy vehicles enter,\ncirculate and exit the site or Works Zone in a forward direction.\n• Deliveries to the site, including loading / unloading materials and\nrequirements for work zones along the road frontage to the development site.\nA Plan is to be included that shows where vehicles stand to load and unload,\nwhere construction plant will stand, location of storage areas for equipment,\nmaterials and waste, locations of Work Zones (if required) and location of\ncranes (if required).\n• Works Zones if heavy vehicles cannot enter or exit the site in a forward\ndirection.\n• Control of pedestrian and vehicular traffic where pre-construction routes are\naffected.\n• Temporary Road Closures.\nWhere the plan identifies that the travel paths of pedestrians and vehicular traffic are\nproposed to be interrupted or diverted for any construction activity related to works\ninside the development site an application must be made to Council for a Road\nOccupancy Licence. Implementation of traffic management plans that address\ninterruption or diversion of pedestrian and/or vehicular traffic must only take place\nfollowing receipt of a Road Occupancy Licence from Council or the Roads and\nMaritime Service where on a classified road.\nWhere a dedicated delivery vehicle loading and unloading zone is required along the\nroad frontage of the development site a Works Zone Application must be lodged and\napproved by Council. A minimum of 3 months is required to allow Local Transport\nforum endorsement and Council approval.\nThe Construction Traffic guidance and Pedestrian Management Plan must be\nreviewed and updated during construction of the development to address any\nchanging site conditions.\nA copy of the Construction Traffic Guidance and Pedestrian Management Plan must\nbe held on site at all times and be made available to Council upon request.\n3.13 The applicant is to engage a project Ecologist to undertake the following prior to\ncommencement of any works including any vegetation clearing works:\n• Mark trees for retention and removal;\n• Undertake a pre-clearance survey prior to any vegetation clearing to locate\nany possible residing fauna, this must include checking for active bird nests;\n• If applicable, any fauna encountered during the pre-clearance survey must be\ncaptured and relocated to adjacent bushland and provided with adequate\nresources and/ or where relevant taken into care by a vet or licenced wildlife\ncarer.\n3.14 Like for Like (Ecosystem Credit Retirement)\n1. Prior to commencement of any works the class and number of ecosystem credits\nin Table 1 must be retired to offset the residual biodiversity impacts of the\ndevelopment.\n2. The requirement to retire ecosystem credits in Table 1 may be satisfied by\npayment to the Biodiversity Conservation Fund of an amount equivalent to the\nclass and number of ecosystem credits, as calculated by the Biodiversity\nConservation Fund Charge System.\n3. Evidence of the retirement of ecosystem credits or payment to the Biodiversity\nConservation Fund must be provided to the consent authority prior to\ncommencement of any works, including prior to any vegetation clearing works.\nTable 1. Ecosystem credits required to be retired - like for like\nImpacted\nplant\ncommunity\ntype\nNumber of\necosystem\ncredits\nHBT IBRA sub-region Plant community type(s)\nthat can be used to\noffset the impacts from\ndevelopment\n3433-Hunter\nCoast Foothills\nSpotted Gum-\nIronbark\nGrassy Forest\n2 Yes Wyong , Hunter,\nPittwater and\nYengo.\nor\nAny IBRA\nsubregion that is\nwithin 100\nkilometres of the\nouter edge of the\nimpacted site.\nHunter-Macleay Dry\nSclerophyll Forests This\nincludes PCT's: 1608, 3431,\n3433, 3436, 3437, 3439,\n3442, 3444, 3446\nLike for Like (Species Credit Retirement)\n1. Prior to commencement of any works the class and number of species credits in\nTable 2 must be retired to offset the residual biodiversity impacts of the\ndevelopment.\n2. The requirement to retire species credits outlined in Table 2 may be satisfied by\npayment to the Biodiversity Conservation Fund of an amount equivalent to the\nclass and number of species credits, as calculated by the Biodiversity\nConservation Fund Charge System.\n3. Evidence of the retirement of ecosystem credits or payment to the Biodiversity\nConservation Fund must be provided to the consent authority prior to\ncommencement of any works, including prior to any vegetation clearing works.\nTable 2. Species credits required to be retired - like for like\nImpacted species credit species Number of\nspecies credits\nIBRA sub-\nregion\nLathamus discolour (Swift Parrot) 3 Anywhere in\nNSW\n3.15. Comply with and implement all impact mitigation recommendations and measures\noutlined in the submitted Environmental Impact Statement (Baker Ryan Stewart, April\n2024) and ecological impact mitigation measures outlined in Section 6 of the\nsupporting Biodiversity Development Assessment Report (Narla Environmental,\nOctober 2025) and tree protection measures outlined in the supporting Arboricultural\nImpact Assessment (Blues Bros Arboriculture, July 2025).\nWhere the recommendations contained within the Environmental Impact Statement,\nBiodiversity Development Assessment Report and Arboricultural Impact Assessment\nare inconsistent, the conditions of consent prevail.\n3.16 Ensure that all parties / trades working on the site are fully aware of their\nresponsibilities with respect to tree protection conditions.\n3.17 Trees T1 (Sydney Turpentine) and T5 (Spotted Gum) and T6 (Spotted Gum) are to be\nretained and protected in accordance with the Arboricultural Impact Assessment,\nprepared by Blues Bros, dated 2 July 2025 (Version 2). Tree protection fencing is to be\nestablished around these three trees as per the recommendations of the Arborist\nreport under Section 7.3.4.\nErect a 1.8 metre high chain mesh fence around Tree Protection Zones that must\nremain intact until construction is completed.\nSign-post fences around Tree\nProtection Zones to warn of its purpose.\nTrees to be retained are to be protected by fencing in accordance with Australian\nStandard AS 4970-2009: Protection of Trees on Development Sites. All required tree\nprotection measures are to be maintained for the duration of construction works.\n4. DURING WORKS\n4.1 All conditions under this section must be met during works.\n4.2 The principal certifier must ensure that building work, demolition or vegetation\nremoval is only carried out between:\n7.00 am and 5.00 pm on Monday to Saturday\nThe principal certifier must ensure building work, demolition or vegetation removal is\nnot carried out on Sundays and public holidays, except where there is an emergency.\nUnless otherwise approved within a construction site management plan, construction\nvehicles, machinery, goods or materials must not be delivered to the site outside the\napproved hours of site works.\nNote: Any variation to the hours of work requires Council’s approval.\n4.3 While construction or demolition is being carried out, all such works must cease\nimmediately if a relic or Aboriginal object is unexpectedly discovered. The applicant\nmust notify the Heritage Council of NSW in respect of a relic and notify the Secretary\nof the Department of Planning, Industry and Environment and the Heritage Council of\nNSW in respect of an Aboriginal object. Building work may recommence at a time\nconfirmed by either the Heritage Council of NSW or the Secretary of the Department\nof Planning, Industry and Environment.\nIn this condition:\n“relic” means any deposit, artefact, object or material evidence that:\n(a) relates to the settlement of the area that comprises New South Wales, not\nbeing Aboriginal settlement, and\n(b) is of State or local heritage significance; and\n“Aboriginal object” means any deposit, object or material evidence (not being a\nhandicraft made for sale) relating to the Aboriginal habitation of the area that\ncomprises New South Wales, being habitation before or concurrent with (or both) the\noccupation of that area by persons of non-Aboriginal extraction and includes\nAboriginal remains. To ensure the protection of objects of potential sign\n4.4 Implement and maintain all erosion and sediment control measures and undertake\nworks in accordance with the approved Erosion and Sediment Control Plan prepared\nby Eclipse Consulting Engineers dated 22.04.2024. Update the plan as required during\nall stages of the construction or in accordance with the ‘Blue Book’ (Managing Urban\nStormwater: Soils and Construction, Landcom, 2004).\n4.5 Keep a copy of the stamped approved plans on-site for the duration of site works and\nmake the plans available upon request to either the Principal Certifying Authority or an\nofficer of Council.\n4.6 Notify Council when plumbing and drainage work will be ready for inspection(s) and\nmake the work accessible for inspection in accordance with the Plumbing and Drainage\nAct 2011.This condition only applies if no installation / alteration of plumbing and / or\ndrainage works are proposed (excludes stormwater drainage).\n4.7 Place all building materials, plant and equipment on the site of the development\nduring the construction phase of the development so as to ensure that pedestrian and\nvehicular access within adjoining public roads, footpaths and reserve areas, is not\nrestricted and to prevent damage to public infrastructure. Further, no construction\nwork is permitted to be carried out within the road reserve unless the works are\nassociated with a separate approval issued under the provisions of the Roads Act 1993.\n4.8 Re-use, recycle or dispose of all building materials in accordance with the Waste\nManagement Plan submitted with the subject application. (BU026)\n4.9 Arrange with the relevant service provider / Authority (e.g. Ausgrid, Jemena,\ncommunications provider) for the supply of services concurrently with the engineering\nwork approved by this consent. Arrangements must include, where required, any\nrelocation of existing mains and services, and dedication of easements for mains and\nservices.\n4.10 During construction works, all cut or fill is to be constructed in such a manner that\nsurface water will not be permanently or temporarily diverted to adjoining land and so\nthat natural drainage from adjoining land will not be obstructed or affected.\n4.11 While building work is being carried out and where no noise and vibration\nmanagement plan is approved under this consent, the applicant is to ensure that any\nnoise caused by demolition, vegetation removal or construction does not exceed an\nLAeq (15 min) of 5dB(A) above background noise, when measured at any lot boundary\nof the property where the construction is being carried out.\n4.12 Provide and maintain a garbage receptacle at the work site until the works are\ncompleted. The garbage receptacle must have a tight-fitting lid and be suitable for\nfood scraps and papers.\n4.13. Supervision by a suitably qualified Ecologist is required for all vegetation clearing and\nconstruction works. The Ecologist must:\n• Mark trees for retention and removal\n• Provide an environmental induction to civil contractors and subcontractors\n• Supervise clearing, removal of habitat trees and earthworks\nThe Ecologist must provide updates in writing to Council’s Ecologist upon completion\nof the above environmental control measures.\n4.14. Implement the following fauna welfare measures during clearing:\n• Supervision by Ecologist\nRemoval of hollow bearing trees and log habitat on the ground must be\nundertaken under the supervision and guidance of a suitably qualified\nEcologist or licensed wildlife handler.\n• Pre-Clearing Inspection\nThe Ecologist is to inspect all potential habitat trees prior to removal and\nidentify evidence of fauna use.\n• Fauna Welfare\nPrior to the felling of hollow bearing trees, hollows are to be visually\ninspected. Should a threatened species be positively identified, all clearing\nworks are to cease and the advice of Council or the Office of Department of\nPlanning, Industry and Environment must be sought. When fauna are present,\nthe animals are to be removed and suitably relocated by the Ecologist prior to\nfelling, or the hollows are to be blocked with rags or similar material and the\nhollows sectionally dismantled and lowered carefully to the ground. The\nEcologist is to work in conjunction with the machinery operator to identify the\nmost benign method of dislodging fauna and for felling trees. Wildlife must\nbe relocated locally to an area with adequate resources. Any fauna rescued\nduring vegetation clearance is to be assessed for injuries and, if unharmed,\nsubsequently released into suitable nearby habitat. Captured fauna may be\nheld until dusk prior to release in accordance with relevant animal ethics\nlicensing and standards. If any fauna is injured during vegetation clearing they\nare to be taken promptly for treatment to a nearby veterinarian or wildlife\ncarer.\n• Reporting\nFollowing the removal of hollow bearing trees, the Ecologist must notify\nCouncil’s Ecologist/Environment Officer in writing of compliance with this\ncondition within fourteen (14) days. Information provided must include fauna\nobservations, number, size of hollows.\n• Squirrel Glider Habitat\nClearing of native vegetation or trees is to be carried out in accordance with\nthe clearing protocol outlined in the Squirrel Glider Conservation\nManagement Plan (Smith, 2002).\n4.15. Manage native fauna appropriately during clearing and construction phase of the\napproved works. In this regard, an appropriately licensed Ecologist is to be engaged\nto advise and supervise the clearing of trees. Where, in spite of precautions, wildlife\nis injured, the Ecologist is to take the necessary action to treat the animal, which may\ninclude veterinary treatment or transfer of the animal to a volunteer wildlife carer\ngroup such as WIRES or Wildlife Arc.\n4.16. Remove hollow bearing trees under the advice and supervision of a qualified and\nexperienced Ecologist who holds an appropriate licence to mitigate against any\nanimal welfare issues. The Ecologist is to inspect all potential habitat trees prior to\nremoval and identify evidence of fauna use. Should a threatened species be\npositively identified, all clearing works are to cease and the advice of Council or the\nOffice of Department of Planning, Industry and Environment must be sought. When\nfauna are present, the animals are to be removed and suitably relocated by the\nEcologist prior to felling or the tree must be sectionally dismantled under the\nsupervision of the Ecologist before relocating animals. Wildlife must be relocated\nlocally to an area with adequate resources.\n4.17. Utilise timber from felled native trees by:\n• Re- instating logs as ground habitat in areas of retained vegetation, and/or\n• Wood chip or tub grind into mulch for landscaping, soil stabilisation or bush\nregeneration, and/or\n• Using for firewood (but not piled burned on-site); and/or\n• Recycling for use in construction materials, furniture or fencing.\n4.18. Undertake clearing and vegetation management in accordance with the approved\ntree removal/retention plan provided in the submitted Arboricultural Impact\nAssessment (Blues Bros Arboriculture, July 2025). Trees must be removed in such a\nmanner so as to prevent damage to surrounding trees to be retained.\n4.19 Comply with and implement all impact mitigation recommendations and measures\noutlined in the submitted Environmental Impact Statement (Baker Ryan Stewart, April\n2024) and ecological impact mitigation measures outlined in Section 6 of the\nsupporting Biodiversity Development Assessment Report (Narla Environmental,\nOctober 2025) and tree protection measures outlined in the supporting Arboricultural\nImpact Assessment (Blues Bros Arboriculture, July 2025).\nWhere the recommendations contained within the Environmental Impact Statement,\nBiodiversity Development Assessment Report and Arboricultural Impact Assessment\nare inconsistent, the conditions of consent prevail.\n4.20 Design, locate and install any underground services to minimise or prevent tree root\ndamage in accordance with Australian Standard AS 4970-2009: Protection of Trees on\nDevelopment Sites.\n4.21 All required tree protection measures are to be maintained for the duration of\nconstruction works. Activities generally excluded from the Tree Protection Zone, but\nnot limited to:\n• Machine excavation, trenching, material storage, prepare chemicals or\ncement, park, refuel, dump waste, wash down, fill or change soil level.\n4.22 Install outdoor lighting in accordance with AS/NZS 4282:2023 Control of the Obtrusive\nEffects of Outdoor Lighting.\n4.23 The removal of the smaller (middle) demountable structure labelled “existing\nstaff/lunchroom”.\n5. PRIOR TO ISSUE OF ANY OCCUPATION CERTIFICATE\n5.1 All conditions under this section must be met prior to the issue of any Occupation\nCertificate.\n5.2 Obtain an Environmental Protection Licence from the NSW Environmental Protection\nAuthority for the activity.\n5.3 Obtain the Section 307 Certificate of Compliance under the Water Management Act\n2000 for water and sewer requirements for the development from Central Coast\nCouncil as the Water Supply Authority, prior to issue of the Occupation Certificate.\n5.4 Construct any additional civil works, where required by Council, to ensure satisfactory\ntransitions to existing site formations and pavements where designs contained in the\nRoads Act Works Approval do not adequately address transition works.\n5.5 Complete construction of the stormwater management system in accordance with the\nStormwater Management Plan and Australian Standard AS 3500.3-Stormwater\ndrainage systems. Certification of the construction by a suitably qualified consultant\nmust be provided to the Principal Certifier.\n5.6 Complete construction of all works within the road reserve in accordance with the\nRoads Act Works Approval. Completion of works includes the submission and\nacceptance by Council of all work as executed drawings plus other construction\ncompliance documentation and payment of a maintenance/defects bond to Council in\naccordance with Council’s Fees and Charges.\n5.7 Repair any damage to Council’s infrastructure and road reserve as agreed with Council.\nDamage not shown in the dilapidation report submitted to Council before the\ndevelopment works had commenced will be assumed to have been caused by the\ndevelopment works unless the Developer can prove otherwise.\n5.8 Complete construction of all works approved in the Local Government Act Section 68\nStormwater Drainage Works Approval. Completion includes the submission and\nacceptance by Council of all work as executed drawings plus other construction\ncompliance documentation and payment of a maintenance/defects bond to Council in\naccordance with Council’s adopted fees and charges.\n5.9 Complete the civil engineering works within the development site in accordance with\nthe detailed design drawings and design reports plans within the construction\ncertificate.\n5.10 Include on Certificate of Title under the Conveyancing Act 1919 for the following\nrestrictive covenants; with Council having the benefit of these covenants and having\nsole authority to release and modify. Wherever possible, the extent of land affected by\nthese covenants must be defined by bearings and distances shown on the plan. The\nplan and instrument must:\na) Create a ‘Restriction on the use of Land’ over all lots containing an on-site\nstormwater detention system restricting any alterations to such a facility or the\nerection of any structure over the facility or the placement of any obstruction\nover the facility.\nb) Create a ‘Restriction on the use of Land’ over all lots containing a nutrient /\npollution control facility restricting any alteration to such a facility or the erection\nof any structure over the facility or the replacement of any obstruction over the\nfacility.\nNote: Standard wording, acceptable to Council, for covenants can be obtained by\ncontacting Council Subdivision Certificate Officer.\n5.11 Include on the on Certificate of Title a positive covenant by the registered proprietor in\nfavour of Council pursuant to the Conveyancing Act 1919 establishing the following\nwith the authority empowered to release, vary or modify the positive covenant is\nCentral Coast Council.\na) Ensure on any lot containing an on-site stormwater detention system that:\n(i) the facility will remain in place and fully operational\n(ii) the facility is maintained so that it operates in a safe and efficient\nmanner\n(iii) Council staff is permitted to inspect and repair the facility at the\nowner's cost\n(iv) Council is indemnified against all claims of compensation caused by\nthe facility\nb) Ensure on any lot containing a nutrient/pollution control facility that:\n(i) the facility will remain in place and fully operational\n(ii) the facility is maintained so that it operates in a safe and efficient\nmanner\n(iii) Council staff is permitted to inspect and repair the facility at the\nowner's cost\n(iv) Council is indemnified against all claims of compensation caused by\nthe facility\nNote: Standard wording, acceptable to Council, for covenants can be obtained by\ncontacting Council Subdivision Certificate Officer.\n5.12 Complete the landscaping works in accordance with the approved plans and\nspecification.\n5.13 Provide the Principal Certifier with written certification from a qualified landscape\ndesigner certifying that landscaping has been implemented in accordance with the\napproved landscape plan as amended by any conditions of this consent.\n5.14 Prepare and submit a final certification report detailing the level of compliance for\neach stage of the development. The report with all conditions relating to ecology be\nprepared by the engaged Ecologist and forwarded to Council for review.\n5.15 Classify all excavated material removed from the site in accordance with NSW EPA\n(2014) Waste Classification Guidelines prior to disposal. All excavated material must be\ndisposed of to an approved waste management facility, and receipts of the disposal\nmust be kept on-site.\n5.16 Complete any building works in accordance with the relevant provisions and\nrequirements of the National Construction Code Series.\n5.17 Line mark and identify a minimum of 13 off-street car parking for staff visitors to the\nbuilding including an accessible space.\n5.18 Submit a Certificate of Compliance for all plumbing and drainage work and a Sewer\nService Diagram showing sanitary drainage work (to be provided by licensed plumber)\nin accordance with the Plumbing and Drainage Act 2011, where required.\n6. ONGOING\n6.1. Comply with all requirements in the Environmental Protection Licence (EPL) from the\nNSW Environmental Protection Authority for the activity. Operate and manage the\nsite in accordance with the EPL.\n6.2 Comply with and implement all impact mitigation recommendations and measures\noutlined in the submitted Environmental Impact Statement (Baker Ryan Stewart, April\n2024) and ecological impact mitigation measures outlined in Section 6 of the\nsupporting Biodiversity Development Assessment Report (Narla Environmental,\nOctober 2025) and tree protection measures outlined in the supporting Arboricultural\nImpact Assessment (Blues Bros Arboriculture, July 2025).\nWhere the recommendations contained within the Environmental Impact Statement,\nBiodiversity Development Assessment Report and Arboricultural Impact Assessment\nare inconsistent, the conditions of consent prevail.\n6.3 Implement the approved routine storm water quality monitoring program and submit\nmonthly reports to Council for a minimum 3 months.\n6.4 Restrict the shear/bailer to process no more than 150 tonnes of scrap metal per day.\n6.5 Restrict the hours of operation of the activity to those times listed below:\nMonday - Friday: 7.30am - 5:00pm\nSaturday: 7.30am - 2:00pm\nSunday/Public Holidays: No operation\nAny variation to these hours is subject to the prior consent of Council.\n6.6 No asbestos waste is to be accepted or stored at the premises.\n6.7 Operate the site in accordance with the Operations & Management Plan, (Barker Ryan\nStewart, April 2024) and NSW EPA Environmental Protection Licence.\n6.8 Maintain all boundary front/perimeter fencing for the life of the development in the\napproved location.\n6.9 Load and unload delivery vehicles wholly within the site. Delivery vehicles must enter\nand exit the site in a forward direction.\n6.10 Maintain the site landscaping for the life of the development.\n6.11 Replace all damaged, dead or missing areas of lawn and plantings at the completion of\nthe landscaping maintenance period, including adjoining road reserve areas that are in\na state of decline, to a healthy and vigorous condition in accordance with the approved\ndetailed Landscape Plans and Development Consent Conditions.\n6.12 Maintain internal pavement and pavement marking.\n6.13 Do not expose goods for sale, hire or other reward.\n6.14 All stockpiles are to be suitably managed at all times to ensure no encroachment on to\nadjoining properties or the street. All waste stockpiles are to be contained within the\nnominated areas.\n6.15 All operational areas (i.e. other than the nominated landscaped areas, buildings and\nbasin) are to be concrete sealed hardstand.\n6.16 No caretaker is to reside on the site. No residential activities are permitted.\n6.17 Do not erect advertising sign(s) on or in conjunction with the use and / or\ndevelopment without development consent unless the advertisement is exempt\ndevelopment or otherwise permitted without development consent.\n6.18 Do not use any flashing light, animated or reflective or moving parts, iridescent or\nfluorescent colours or materials on the external surface of the advertising sign. The\ncolours exhibited on the sign must be in keeping with the amenity of the surrounding\narea.\n6.19 The management and mitigation measures identified under Section 9 and 10 of the EIS\nprepared by Barker Ryan Stewart are to be implemented under the operation of the\ndevelopment.\n6.20 Maintain all works associated with the approved Landscape Plans for a period of twelve\n(12) months from the date of the issue of any Occupation Certificate to ensure the\nsurvival and establishment of the landscaping.\n6.21 Replace all damaged, dead or missing areas of lawn and plantings at the completion of\nthe landscaping maintenance period, including adjoining road reserve areas that are in\na state of decline, to a healthy and vigorous condition in accordance with the approved\ndetailed Landscape Plans and Development Consent Conditions.\n6.22 Operate and maintain all external lighting so as not to impact on any adjoining\nproperty.\n6.23 This consent includes the ‘use only’ of the existing demountable structure as an ‘office\nand administration’ building as shown on the plans\n6.24 The existing shed is not to include any office activities or similar uses without further\nconsent.\nPENALTIES\n1.1. Failure to comply with this development consent and any condition of this consent\nmay be a criminal offence. Failure to comply with other environmental laws may also\nbe a criminal offence.\nWhere there is any breach Council may without any further warning:\n• Issue Penalty Infringement Notices (On-the-spot fines);\n• Issue notices and orders;\n• Prosecute any person breaching this consent, and/or\n• Seek injunctions/orders before the courts to retain and remedy any breach.\nWarnings as to Potential Maximum Penalties\nMaximum Penalties under NSW Environmental Laws include fines up to $1.1 Million\nand / or custodial sentences for serious offences.","stage":"general","stage_basis":"heading","page":3}]});
